"""Autogenerated YouTube transcripts -> TSV of (seconds, chapter, text), noise markers removed."""
import re, os, csv, glob

HERE = os.path.dirname(os.path.abspath(__file__))
RAW = os.path.join(HERE, "..", "reference", "raw")
CLEAN = os.path.join(HERE, "..", "reference", "clean")

# "0:1313 seconds", "1:051 minute, 5 seconds", "1:02:031 hour, 2 minutes, 3 seconds"
STAMP = re.compile(r"^(?:(\d+):)?(\d+):(\d\d)(?:\d+ hours?,? ?)?(?:\d+ minutes?,? ?)?(?:\d+ seconds?)?")
NOISE = re.compile(r"\[(?:Music|Applause|Laughter|Sound|Noise|__)\]", re.I)

for name in sorted(os.path.splitext(os.path.basename(p))[0] for p in glob.glob(os.path.join(RAW, "*.txt"))):
    rows, chapter, dropped = [], "", 0
    for line in open(os.path.join(RAW, name + ".txt"), encoding="utf-8"):
        line = line.strip()
        if not line:
            continue
        if line.startswith("Chapter "):
            chapter = line
            continue
        m = STAMP.match(line)
        if not m:  # video titles, "Sync to video time" and other page furniture
            dropped += 1
            continue
        h, mnt, s = m.groups()
        secs = int(h or 0) * 3600 + int(mnt) * 60 + int(s)
        text = NOISE.sub("", line[m.end():]).strip()
        if not text:
            dropped += 1
            continue
        rows.append((secs, chapter, text))
    with open(os.path.join(CLEAN, name + ".tsv"), "w", encoding="utf-8", newline="") as f:
        csv.writer(f, delimiter="\t").writerows(rows)
    words = sum(len(r[2].split()) for r in rows)
    unstamped = sum(1 for r in rows if r[0] is None)
    print(f"{name}: {len(rows)} text rows, {words} words, {dropped} noise-only rows dropped, {unstamped} unstamped rows")
